'use client'

import { useEffect, useMemo, useState } from 'react'
import { useRouter } from 'next/navigation'
import { ArrowUpRight, Bell, BookOpen, Building2, Check, ClipboardList, CreditCard, Download, FileText, LayoutDashboard, LogOut, Menu, Package, Plus, Printer, Receipt, Search, Settings, Share2, ShoppingCart, Upload, Users, WalletCards, Wifi, X } from 'lucide-react'
import { createClient } from '@/lib/supabase/client'
import { DownloadPanel } from '@/components/download-panel'
import { offlineDb } from '@/lib/offline-db'
import { startSync, syncNow } from '@/lib/sync'

type Module = 'Overview' | 'Point of Sale' | 'Inventory' | 'Customers' | 'Credit & Debtors' | 'Accounting' | 'Expenses' | 'Staff' | 'Branches' | 'Quotations'
type Product = { name: string; sku: string; category: string; cost: number; price: number; stock: number }
type Customer = { name: string; phone: string; location: string; outstanding: number }
type Sale = { id: string; customer: string; total: number; paid: number; date: string }
type Overlay = 'audit' | 'devices' | 'roles' | 'branch' | null

const money = (n: number) => `₦${n.toLocaleString('en-NG')}`
const nav: [typeof LayoutDashboard, Module][] = [[LayoutDashboard, 'Overview'], [ShoppingCart, 'Point of Sale'], [Package, 'Inventory'], [Users, 'Customers'], [CreditCard, 'Credit & Debtors'], [BookOpen, 'Accounting'], [Receipt, 'Expenses'], [Users, 'Staff'], [Building2, 'Branches'], [FileText, 'Quotations']]
const initialProducts: Product[] = [{ name: 'Golden Penny Spaghetti', sku: 'GP-SPAG-500', category: 'Groceries', cost: 650, price: 850, stock: 42 }, { name: 'Peak Milk 400g', sku: 'PEAK-400', category: 'Dairy', cost: 2500, price: 3200, stock: 8 }, { name: 'Dettol Liquid 250ml', sku: 'DET-250', category: 'Personal care', cost: 1400, price: 1850, stock: 24 }, { name: 'Indomie Chicken 70g', sku: 'IND-70', category: 'Groceries', cost: 480, price: 650, stock: 0 }, { name: 'Eva Water 1.5L', sku: 'EVA-15', category: 'Beverages', cost: 500, price: 700, stock: 96 }]
const initialCustomers: Customer[] = [{ name: 'Chidi Okoro', phone: '0803 445 2101', location: 'Lekki, Lagos', outstanding: 42000 }, { name: 'Blessing Adeyemi', phone: '0816 220 8834', location: 'Ikoyi, Lagos', outstanding: 0 }, { name: 'Musa Ibrahim', phone: '0705 128 4472', location: 'Ajah, Lagos', outstanding: 18500 }]

function Button({ children, onClick, variant = 'primary', type = 'button' }: any) { return <button type={type} onClick={onClick} className={`flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold shadow-sm transition duration-200 hover:-translate-y-0.5 active:translate-y-0 ${variant === 'primary' ? 'bg-[#2f7047] text-white shadow-[#2f7047]/20 hover:bg-[#245d39] hover:shadow-lg' : 'border border-[#d8e5d8] bg-white/80 text-[#487054] hover:border-[#9ec5a4] hover:bg-[#f4faf3]'}`}>{children}</button> }
function Card({ children, className = '' }: any) { return <div className={`dashboard-card rounded-[22px] border border-[#e3ebe2]/90 bg-white/90 backdrop-blur-sm transition-shadow ${className}`}>{children}</div> }
function Heading({ eyebrow, title, description, action }: any) { return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><div className="mb-3 inline-flex items-center gap-2 rounded-full bg-[#e8f4e8] px-3 py-1 text-[10px] font-bold uppercase tracking-[0.14em] text-[#39724a]">{eyebrow}</div><h1 className="text-[30px] font-bold tracking-[-0.05em] text-[#183022] sm:text-[34px]">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#7d8980]">{description}</p></div>{action}</div> }
function Stat({ label, value, detail, orange = false }: any) { return <div className="dashboard-card rounded-[20px] border border-[#e3ebe2] bg-white/90 p-5"><div className="flex items-center justify-between text-xs font-medium text-[#89958c]"><span>{label}</span><span className={`size-2 rounded-full ${orange ? 'bg-[#d98a3b]' : 'bg-[#62a66f]'}`} /></div><div className="mt-3 text-[27px] font-bold tracking-[-0.04em] text-[#1d2b22]">{value}</div><div className={`mt-1 text-[11px] font-semibold ${orange ? 'text-[#b7782f]' : 'text-[#4d9563]'}`}>{detail}</div></div> }

export default function Page() {
  const [active, setActive] = useState<Module>('Overview')
  const [mobileNav, setMobileNav] = useState(false)
  const [products, setProducts] = useState(initialProducts)
  const [customers, setCustomers] = useState(initialCustomers)
  const [cart, setCart] = useState<{ product: Product; qty: number }[]>([])
  const [customer, setCustomer] = useState('Walk-in customer')
  const [paid, setPaid] = useState('')
  const [query, setQuery] = useState('')
  const [modal, setModal] = useState<'product' | 'customer' | 'employee' | null>(null)
  const [overlay, setOverlay] = useState<Overlay>(null)
  const [sales, setSales] = useState<Sale[]>([])
  const [notice, setNotice] = useState('')
  const [syncState, setSyncState] = useState<'Online' | 'Offline' | 'Syncing…'>('Online')
  const [waiting, setWaiting] = useState(0)
  const [showDevSync, setShowDevSync] = useState(false)
  const [employees, setEmployees] = useState([
    { id: 'ada', name: 'Ada Nwosu', username: 'ada@greenbasket.ng', role: 'Manager', branches: 'Lekki, Ikeja', status: 'Active', login: 'Today, 09:42' },
    { id: 'samuel', name: 'Samuel Okafor', username: 'samuel@greenbasket.ng', role: 'Cashier', branches: 'Lekki branch', status: 'Active', login: 'Today, 08:15' },
    { id: 'ifeoma', name: 'Ifeoma Bello', username: 'ifeoma@greenbasket.ng', role: 'Accountant', branches: 'All branches', status: 'Active', login: 'Yesterday, 17:30' },
    { id: 'chinedu', name: 'Chinedu Obi', username: 'chinedu@greenbasket.ng', role: 'Stock Keeper', branches: 'Ajah branch', status: 'Suspended', login: 'Sep 24, 14:10' },
  ])
  const [editingEmployee, setEditingEmployee] = useState<any>(null)
  const [creatingRole, setCreatingRole] = useState(false)
  const [rolePermissions, setRolePermissions] = useState<Record<string, string[]>>({ Owner: ['Sales', 'Inventory', 'Customers', 'Accounting', 'Expenses', 'Staff'], Manager: ['Sales', 'Inventory', 'Customers', 'Accounting'], Cashier: ['Sales'], 'Stock Keeper': ['Inventory'], Accountant: ['Accounting', 'Expenses'] })
  const [settingsOpen, setSettingsOpen] = useState(false)
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const [businessName, setBusinessName] = useState('Green Basket Mart')
  const [adminName, setAdminName] = useState('Samuel')
  const [logo, setLogo] = useState('')
  const [downloadOpen, setDownloadOpen] = useState(false)
  const [sessionReady, setSessionReady] = useState(false)
  const router = useRouter()

  useEffect(() => {
    createClient().auth.getSession().then(({ data }) => { if (!data.session) router.replace('/login'); else setSessionReady(true) })
    const { data: listener } = createClient().auth.onAuthStateChange((_event, session) => { if (!session) router.replace('/login') })
    return () => listener.subscription.unsubscribe()
  }, [router])

  useEffect(() => {
    const refresh = async () => setWaiting(await offlineDb.outbox.where('status').anyOf('pending', 'failed').count())
    const onComplete = () => { setSyncState('Online'); void refresh() }
    const onError = () => { setSyncState(navigator.onLine ? 'Online' : 'Offline'); void refresh() }
    void refresh()
    const stop = startSync()
    window.addEventListener('offline', () => setSyncState('Offline'))
    window.addEventListener('online', () => setSyncState('Online'))
    window.addEventListener('my-mall-sync-complete', onComplete)
    window.addEventListener('my-mall-sync-error', onError)
    return () => { stop(); window.removeEventListener('my-mall-sync-complete', onComplete); window.removeEventListener('my-mall-sync-error', onError) }
  }, [])

  const filtered = useMemo(() => products.filter(p => `${p.name} ${p.sku} ${p.category}`.toLowerCase().includes(query.toLowerCase())), [products, query])
  const total = cart.reduce((sum, item) => sum + item.product.price * item.qty, 0)
  const due = Math.max(0, total - Number(paid || 0))
  const go = (module: string) => { setActive(module as Module); setMobileNav(false) }
  const showNotice = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(''), 2600) }
  const add = (product: Product) => setCart(current => current.some(item => item.product.sku === product.sku) ? current.map(item => item.product.sku === product.sku ? { ...item, qty: item.qty + 1 } : item) : [...current, { product, qty: 1 }])
  const complete = () => {
    const amountPaid = Number(paid || 0)
    if (!cart.length || amountPaid < 0 || amountPaid > total) return showNotice('Enter a valid payment amount')
    const sale = { id: `SALE-${Date.now()}`, customer, total, paid: amountPaid, date: new Date().toLocaleDateString('en-NG') }
    setSales(current => [sale, ...current])
    setProducts(current => current.map(product => { const line = cart.find(item => item.product.sku === product.sku); return line ? { ...product, stock: Math.max(0, product.stock - line.qty) } : product }))
    if (customer !== 'Walk-in customer' && due) setCustomers(current => current.map(item => item.name === customer ? { ...item, outstanding: item.outstanding + due } : item))
    setCart([]); setPaid(''); showNotice('Sale completed successfully')
  }
  const share = (sale: Sale) => {
    const receipt = `Green Basket Mart\nReceipt ${sale.id}\nCustomer: ${sale.customer}\nTotal: ${money(sale.total)}\nPaid: ${money(sale.paid)}\nBalance: ${money(Math.max(0, sale.total - sale.paid))}`
    if (navigator.share) navigator.share({ title: 'Sales receipt', text: receipt }).catch(() => undefined)
    else void navigator.clipboard?.writeText(receipt)
    showNotice('Receipt copied or ready to share')
  }
  const saveRecord = (data: any) => {
    if (modal === 'product') setProducts(current => [...current, { name: data.name, sku: `SKU-${Date.now()}`, category: data.category, cost: Number(data.cost), price: Number(data.price), stock: Number(data.quantity) }])
    if (modal === 'customer') setCustomers(current => [...current, { name: data.name, phone: data.phone, location: data.location, outstanding: Number(data.outstanding || 0) }])
    if (modal === 'employee') setEmployees(current => [...current, { id: `employee-${Date.now()}`, name: data.name, username: data.username, role: data.role, branches: data.branches, status: data.status || 'Active', login: 'Never' }])
    setModal(null); showNotice('Record saved successfully')
  }
  const saveEmployee = (data: any) => { setEmployees(current => current.map(employee => employee.id === data.id ? { ...employee, ...data } : employee)); setEditingEmployee(null); showNotice('Employee account updated') }
  const updateRolePermission = (role: string, permission: string, enabled: boolean) => setRolePermissions(current => ({ ...current, [role]: enabled ? [...(current[role] || []), permission] : (current[role] || []).filter(item => item !== permission) }))
  const createRole = (name: string, permissions: string[]) => { const role = name.trim(); if (!role) return; setRolePermissions(current => ({ ...current, [role]: permissions })); setCreatingRole(false); showNotice(`${role} role created`) }
  const content = active === 'Overview' ? <Overview go={go} syncState={syncState} /> : active === 'Point of Sale' ? <POS products={products} cart={cart} add={add} total={total} customer={customer} setCustomer={setCustomer} customers={customers} paid={paid} setPaid={setPaid} due={due} complete={complete} sales={sales} share={share} /> : active === 'Inventory' ? <Inventory products={filtered} query={query} setQuery={setQuery} onAdd={() => setModal('product')} /> : active === 'Customers' ? <Customers customers={customers} onAdd={() => setModal('customer')} /> : active === 'Credit & Debtors' ? <CreditBook customers={customers} onAdd={() => setModal('customer')} /> : active === 'Accounting' ? <Accounting sales={sales} /> : active === 'Expenses' ? <Expenses onSaved={showNotice} /> : active === 'Staff' ? <Staff employees={employees} onAdd={() => setModal('employee')} onAction={setOverlay} onManage={setEditingEmployee} rolePermissions={rolePermissions} onPermissionChange={updateRolePermission} onCreateRole={() => setCreatingRole(true)} /> : active === 'Branches' ? <Branches onAction={setOverlay} /> : <Quotations onAction={showNotice} />

  if (!sessionReady) return <div className="flex min-h-screen items-center justify-center bg-[#eef6ee] text-sm font-semibold text-[#39724a]">Checking your secure session…</div>
  const notifications = [{ title: 'New sale completed', detail: 'A new POS sale was recorded.', time: 'Just now' }, { title: 'Dashboard update', detail: 'Your workspace is ready with the latest tools.', time: 'Today' }, { title: 'Inventory attention', detail: 'Some products are low or out of stock.', time: 'Today' }]
  return <div className="dashboard-shell min-h-screen text-[#1c2921]">
    {process.env.NODE_ENV === 'development' && <div className="pointer-events-none fixed bottom-4 right-4 z-40 w-72"><div className="pointer-events-none rounded-2xl border border-[#dce8dc] bg-white p-4 text-xs shadow-xl"><div className="flex items-center justify-between"><b>Offline sync</b><button onClick={() => setShowDevSync(value => !value)} className="pointer-events-auto text-[#387a4f]">{showDevSync ? 'Hide' : 'Inspect'}</button></div>{showDevSync && <div className="mt-3 flex flex-col gap-2"><div>Network: {navigator.onLine ? 'online' : 'offline'}</div><div>Outbox: {waiting} changes</div><button onClick={() => { setSyncState('Syncing…'); void syncNow().then(() => setWaiting(0)) }} className="rounded-lg bg-[#387a4f] px-3 py-2 font-semibold text-white">Force sync</button></div>}</div></div>}
    {notice && <div className="fixed right-5 top-5 z-50 flex items-center gap-2 rounded-xl bg-[#1d5d39] px-4 py-3 text-sm font-semibold text-white shadow-lg"><Check className="size-4" /> {notice}</div>}
    <aside className={`fixed inset-y-0 left-0 z-20 flex w-[260px] flex-col border-r border-[#dfe9df] bg-[#fbfdfb]/95 px-4 py-5 shadow-[8px_0_30px_rgba(37,76,48,.04)] backdrop-blur-xl transition-transform lg:translate-x-0 ${mobileNav ? 'translate-x-0' : '-translate-x-full'}`}><div className="mb-8 flex items-center gap-2 px-2"><div className="flex size-9 items-center justify-center rounded-xl bg-[#387a4f] text-white"><ShoppingCart className="size-5" /></div><div><div className="font-bold">My Mall</div><div className="text-[10px] text-[#87938b]">{businessName.toUpperCase()}</div></div><button onClick={() => setMobileNav(false)} className="ml-auto lg:hidden"><X className="size-5" /></button></div><div className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[0.12em] text-[#a0aaa2]">Workspace</div><nav className="flex flex-col gap-1">{nav.map(([Icon, label]) => <button key={label} onClick={() => go(label)} className={`group flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm transition ${active === label ? 'bg-[#e6f3e7] font-semibold text-[#2f7047] shadow-sm' : 'text-[#748077] hover:bg-[#f1f7f0] hover:text-[#39724a]'}`}><Icon className="size-4" />{label}</button>)}</nav><div className="mt-auto rounded-2xl bg-[#f6f8f5] p-3 text-xs text-[#7b887e]">All changes sync when you reconnect.<div className="mt-2 flex items-center gap-2 font-semibold text-[#39724a]"><Wifi className="size-3" /> {syncState}</div></div></aside>
    <main className="min-h-screen lg:ml-[260px]"><header className="sticky top-0 z-10 flex h-[76px] items-center justify-between border-b border-[#e1e9e0]/80 bg-[#fbfdfb]/80 px-5 backdrop-blur-xl lg:px-10"><button onClick={() => setMobileNav(true)} className="lg:hidden"><Menu className="size-5" /></button><div className="hidden text-sm font-semibold lg:block">Workspace overview</div><div className="ml-auto flex items-center gap-3"><button aria-label="Download page as PDF" onClick={() => setDownloadOpen(true)} className="hidden items-center gap-2 rounded-xl border border-[#d8e5d8] bg-white px-3 py-2 text-xs font-semibold text-[#39724a] hover:bg-[#f4faf3] sm:flex"><Download className="size-4" /> PDF</button><button aria-label="Notifications" onClick={() => setNotificationsOpen(true)} className="relative rounded-xl p-2 text-[#89958c] hover:bg-[#edf6ed]"><Bell className="size-5" /><span className="absolute right-1 top-1 size-2 rounded-full bg-[#d97845] ring-2 ring-[#fbfdfb]" /></button><button aria-label="Settings" onClick={() => setSettingsOpen(true)} className="rounded-xl p-2 text-[#89958c] hover:bg-[#edf6ed]"><Settings className="size-5" /></button><button aria-label="Sign out" onClick={() => void createClient().auth.signOut()} className="rounded-xl p-2 text-[#89958c] hover:bg-[#edf6ed]"><LogOut className="size-5" /></button><div className="flex size-8 items-center justify-center rounded-full bg-[#d9ebd8] text-xs font-bold text-[#39724a]">{adminName.slice(0, 2).toUpperCase()}</div></div></header><div className="p-5 lg:px-10 lg:py-9">{content}</div></main>
    {modal && <RecordModal type={modal} close={() => setModal(null)} save={saveRecord} />}{editingEmployee && <EmployeeEditor employee={editingEmployee} close={() => setEditingEmployee(null)} save={saveEmployee} />}{creatingRole && <RoleCreator close={() => setCreatingRole(false)} save={createRole} />}
    {overlay && <ActionOverlay type={overlay} close={() => setOverlay(null)} />}
    {notificationsOpen && <NotificationPanel items={notifications} close={() => setNotificationsOpen(false)} />}
    {settingsOpen && <SettingsPanel businessName={businessName} adminName={adminName} logo={logo} setBusinessName={setBusinessName} setAdminName={setAdminName} setLogo={setLogo} close={() => setSettingsOpen(false)} save={() => { setSettingsOpen(false); showNotice('Settings saved successfully') }} />}
    {downloadOpen && <DownloadPanel active={active} close={() => setDownloadOpen(false)} selectPage={go} download={() => { setDownloadOpen(false); window.setTimeout(() => window.print(), 100) }} />}
  </div>
}

function Overview({ go, syncState }: any) { return <><Heading eyebrow="Overview" title="Good morning, Samuel" description="Here is what is happening at Green Basket Mart today." action={<Button onClick={() => go('Point of Sale')}><ShoppingCart className="size-4" /> Open POS</Button>} /><div className="mb-6 overflow-hidden rounded-[26px] border border-[#cfe2d0] bg-gradient-to-br from-[#2f7047] via-[#397c50] to-[#1f5937] p-6 text-white shadow-xl shadow-[#2f7047]/15 sm:p-7"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="text-xs font-semibold uppercase tracking-[0.18em] text-[#c5e4c7]">Today at Green Basket</div><div className="mt-2 text-2xl font-bold tracking-[-0.04em]">Keep your shop moving.</div><p className="mt-1 max-w-xl text-sm text-[#d5ead6]">Monitor sales, stock and customer credit from one calm workspace.</p></div><div className="rounded-2xl bg-white/10 px-4 py-3 text-right backdrop-blur"><div className="text-xs text-[#d5ead6]">Sync status</div><div className="mt-1 font-semibold">{syncState}</div></div></div></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><Stat label="Today's sales" value="₦284,500" detail="↑ 12.8% vs yesterday" /><Stat label="Today's profit" value="₦68,420" detail="24.1% margin" /><Stat label="Low stock" value="8 items" detail="Needs attention" orange /><Stat label="Credit owed" value="₦60,500" detail="3 customers" orange /></div><div className="mt-6 grid gap-5 lg:grid-cols-2"><Card className="p-5"><h2 className="font-semibold">Sales this week</h2><div className="mt-7 flex h-44 items-end gap-3">{[42, 58, 48, 76, 64, 88, 72].map((height, index) => <div key={index} className="flex flex-1 flex-col items-center gap-2"><div className="w-full rounded-t-lg bg-[#b9d9bc]" style={{ height: `${height}%` }} /><span className="text-[10px] text-[#9aa49c]">{['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'][index]}</span></div>)}</div></Card><Card className="p-5"><h2 className="font-semibold">Quick actions</h2><div className="mt-4 flex flex-col gap-2"><button onClick={() => go('Accounting')} className="flex items-center gap-3 rounded-xl bg-[#f8f5ed] p-3 text-left text-sm font-medium text-[#a66c27]"> <FileText className="size-4" /> View business reports <ArrowUpRight className="ml-auto size-4" /></button><button onClick={() => go('Quotations')} className="flex items-center gap-3 rounded-xl bg-[#f3f8f2] p-3 text-left text-sm font-medium text-[#39724a]"><FileText className="size-4" /> Create quotation <ArrowUpRight className="ml-auto size-4" /></button></div></Card></div></> }

function POS({ products, cart, add, total, customer, setCustomer, customers, paid, setPaid, due, complete, sales, share }: any) { return <><Heading eyebrow="Point of Sale" title="Make a sale" description="Fast checkout with customer credit tracking." action={<div className="flex items-center gap-2 rounded-xl bg-[#eef5ee] px-3 py-2 text-xs font-semibold text-[#39724a]"><Wifi className="size-3.5" /> Saved offline</div>} /><div className="grid gap-5 lg:grid-cols-[1fr_380px]"><Card className="p-4"><div className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#a0aaa2]" /><input placeholder="Search product or scan barcode" className="h-11 w-full rounded-xl border border-[#e5eae4] pl-9 pr-3 text-sm" /></div><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3">{products.map((product: Product) => <button disabled={!product.stock} onClick={() => add(product)} key={product.sku} className="rounded-xl border border-[#edf0ec] p-3 text-left hover:border-[#a8c8ae] disabled:opacity-45"><Package className="size-5 text-[#39724a]" /><div className="mt-3 truncate text-sm font-semibold">{product.name}</div><div className="mt-1 text-xs text-[#89958c]">{money(product.price)} · {product.stock} left</div></button>)}</div></Card><div className="flex flex-col gap-5"><Card className="p-5"><h2 className="font-semibold">Current sale</h2><label className="mt-4 block text-xs font-semibold text-[#647269]">Customer account<select value={customer} onChange={e => setCustomer(e.target.value)} className="mt-1 h-10 w-full rounded-lg border border-[#e1e8df] bg-white px-3 text-sm"><option>Walk-in customer</option>{customers.map((item: Customer) => <option key={item.phone}>{item.name}</option>)}</select></label><div className="mt-4 flex flex-col gap-2">{cart.map((item: any) => <div key={item.product.sku} className="flex justify-between text-sm"><span>{item.product.name} × {item.qty}</span><b>{money(item.product.price * item.qty)}</b></div>)}</div><div className="mt-4 flex justify-between border-t pt-4 font-bold"><span>Total</span><span>{money(total)}</span></div><label className="mt-4 block text-xs font-semibold text-[#647269]">Amount paid<input type="number" min="0" max={total} value={paid} onChange={e => setPaid(e.target.value)} className="mt-1 h-10 w-full rounded-lg border px-3 text-sm" placeholder="Enter amount received" /></label><div className="mt-3 flex justify-between text-sm"><span>Outstanding</span><b className={due ? 'text-[#b7782f]' : 'text-[#39724a]'}>{money(due)}</b></div><Button onClick={complete}><WalletCards className="size-4" /> Complete sale</Button></Card><Card><div className="flex items-center justify-between border-b p-4"><h2 className="font-semibold">Completed sales</h2><span className="text-xs text-[#89958c]">{sales.length} today</span></div>{sales.length === 0 ? <div className="p-5 text-sm text-[#89958c]">Completed sales will appear here.</div> : sales.map((sale: Sale) => <div key={sale.id} className="flex items-center gap-3 border-b p-4"><div className="min-w-0 flex-1"><b className="block truncate text-sm">{sale.customer}</b><span className="text-xs text-[#89958c]">{sale.id} · {money(sale.total)}</span></div><button title="Share or print receipt" onClick={() => share(sale)} className="rounded-lg border border-[#dfe8de] p-2 text-[#39724a] hover:bg-[#f3f8f2]"><Share2 className="size-4" /></button><button title="Print receipt" onClick={() => window.print()} className="rounded-lg border border-[#dfe8de] p-2 text-[#39724a] hover:bg-[#f3f8f2]"><Printer className="size-4" /></button></div>)}</Card></div></div></> }

function Inventory({ products, query, setQuery, onAdd }: any) { return <><Heading eyebrow="Inventory" title="Products" description="Track cost, selling price, stock and valuation." action={<Button onClick={onAdd}><Plus className="size-4" /> Add product</Button>} /><Card><div className="border-b p-4"><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search products" className="h-9 w-full rounded-lg border px-3 text-xs sm:w-64" /></div>{products.map((product: Product) => { const low = product.stock <= 5; return <div key={product.sku} className={`grid gap-2 border-b px-4 py-4 md:grid-cols-5 ${low ? 'bg-red-50 text-red-900' : ''}`}><div><b className="text-sm">{product.name}</b><div className="text-xs opacity-70">{product.sku}</div></div><div className="text-sm">{product.category}</div><div><small>Cost</small><div className="font-semibold">{money(product.cost)}</div></div><div><small>Selling</small><div className="font-semibold text-[#39724a]">{money(product.price)}</div></div><div><b>{product.stock}</b><div className="text-xs opacity-70">{low ? (product.stock === 0 ? 'Out of stock' : 'Low stock') : 'in stock'}</div></div></div>})}</Card></> }

function Customers({ customers, onAdd }: any) { return <><Heading eyebrow="Customers" title="Customer book" description="Customer contacts and outstanding balances." action={<Button onClick={onAdd}><Plus className="size-4" /> Add customer</Button>} /><Card><div className="border-b p-4 font-semibold">Customer records</div>{customers.map((customer: Customer) => <div key={customer.phone} className="flex flex-wrap items-center gap-3 border-b p-4"><div className="flex-1"><b>{customer.name}</b><div className="text-xs text-[#89958c]">{customer.phone} · {customer.location}</div></div><b className={customer.outstanding ? 'text-[#b7782f]' : 'text-[#89958c]'}>{customer.outstanding ? `${money(customer.outstanding)} outstanding` : 'No outstanding balance'}</b></div>)}</Card></> }
function CreditBook({ customers, onAdd }: any) { return <><Heading eyebrow="Credit & Debtors" title="Credit book" description="Track balances and part-payments." action={<Button onClick={onAdd}><Plus className="size-4" /> Add customer</Button>} /><Customers customers={customers} onAdd={onAdd} /></> }

function Accounting({ sales }: any) { const [period, setPeriod] = useState('This month'); const salesTotal = sales.reduce((sum: number, sale: Sale) => sum + sale.total, 0); const paidTotal = sales.reduce((sum: number, sale: Sale) => sum + sale.paid, 0); const expenses = 82300; const gross = Math.max(0, salesTotal - salesTotal * 0.76); const downloadSalesHistory = () => { const rows = sales.map((sale: Sale) => `<tr><td>${sale.id}</td><td>${sale.date}</td><td>${sale.customer}</td><td>${money(sale.total)}</td><td>${money(sale.paid)}</td><td>${money(Math.max(0, sale.total - sale.paid))}</td></tr>`).join(''); const html = `<html><head><meta charset="UTF-8"><style>table{border-collapse:collapse;font-family:Arial}th,td{border:1px solid #d9e2d8;padding:8px;text-align:left}th{background:#e8f3e8}</style></head><body><h2>Green Basket Mart — Completed Sales History</h2><table><thead><tr><th>Sale ID</th><th>Date</th><th>Customer</th><th>Total</th><th>Paid</th><th>Balance</th></tr></thead><tbody>${rows || '<tr><td colspan="6">No completed sales</td></tr>'}</tbody></table></body></html>`; const blob = new Blob([html], { type: 'application/vnd.ms-excel;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `sales-history-${new Date().toISOString().slice(0, 10)}.xls`; link.click(); URL.revokeObjectURL(url) }; return <><Heading eyebrow="Accounting" title="Business accounts" description="A clear view of income, profitability, cash flow and business position." action={<div className="flex flex-wrap gap-2"><Button variant="outline" onClick={downloadSalesHistory}><FileText className="size-4" /> Download Excel</Button><Button variant="outline" onClick={() => window.print()}><Printer className="size-4" /> Print report</Button></div>} /><Card className="p-5"><div className="flex flex-wrap items-end gap-3"><label className="text-xs font-semibold">Reporting period<select value={period} onChange={e => setPeriod(e.target.value)} className="mt-1 block h-10 rounded-lg border bg-white px-3 text-sm"><option>This month</option><option>This week</option><option>Today</option><option>Custom range</option></select></label>{period === 'Custom range' && <><label className="text-xs font-semibold">From<input type="date" className="mt-1 block h-10 rounded-lg border px-3" /></label><label className="text-xs font-semibold">To<input type="date" className="mt-1 block h-10 rounded-lg border px-3" /></label></>}<Button onClick={() => undefined}>Apply period</Button></div></Card><Card className="mt-5 overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b p-5"><div><h2 className="font-semibold">Completed sales history</h2><p className="mt-1 text-xs text-[#89958c]">Every completed sale recorded in this session.</p></div><span className="rounded-full bg-[#edf6ed] px-3 py-1 text-xs font-semibold text-[#39724a]">{sales.length} {sales.length === 1 ? 'sale' : 'sales'}</span></div><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-sm"><thead className="bg-[#f8faf7] text-xs text-[#758278]"><tr><th className="px-5 py-3 font-semibold">Sale ID</th><th className="px-5 py-3 font-semibold">Date</th><th className="px-5 py-3 font-semibold">Customer</th><th className="px-5 py-3 font-semibold">Total</th><th className="px-5 py-3 font-semibold">Paid</th><th className="px-5 py-3 font-semibold">Balance</th></tr></thead><tbody>{sales.length ? sales.map((sale: Sale) => <tr key={sale.id} className="border-t"><td className="px-5 py-4 font-semibold text-[#39724a]">{sale.id}</td><td className="px-5 py-4 text-[#657268]">{sale.date}</td><td className="px-5 py-4">{sale.customer}</td><td className="px-5 py-4 font-semibold">{money(sale.total)}</td><td className="px-5 py-4 text-[#39724a]">{money(sale.paid)}</td><td className="px-5 py-4 text-[#b7782f]">{money(Math.max(0, sale.total - sale.paid))}</td></tr>) : <tr><td colSpan={6} className="px-5 py-10 text-center text-sm text-[#89958c]">No completed sales yet. Completed POS transactions will appear here.</td></tr>}</tbody></table></div></Card><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4"><Stat label="Sales / income" value={money(salesTotal || 1284500)} detail={period} /><Stat label="Gross profit" value={money(gross || 316420)} detail="After cost of goods" /><Stat label="Expenses" value={money(expenses)} detail="Operating costs" orange /><Stat label="Net profit" value={money((gross || 316420) - expenses)} detail="Income less expenses" /></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><Card className="p-5"><h2 className="font-semibold">Profit and loss</h2><div className="mt-4 flex flex-col gap-3">{[['Income from sales', money(salesTotal || 1284500)], ['Cost of goods sold', money((salesTotal || 1284500) * .76)], ['Gross profit', money(gross || 316420)], ['Operating expenses', money(expenses)], ['Net profit', money((gross || 316420) - expenses)]].map(([label, value]) => <div key={label} className="flex justify-between border-b pb-3 text-sm"><span className="text-[#6f7d73]">{label}</span><b>{value}</b></div>)}</div></Card><Card className="p-5"><h2 className="font-semibold">Business snapshot</h2><div className="mt-4 grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-[#f3f8f2] p-4"><span className="text-xs text-[#6f7d73]">Cash received</span><b className="mt-2 block text-lg">{money(paidTotal || 1284500)}</b></div><div className="rounded-xl bg-[#fff7eb] p-4"><span className="text-xs text-[#6f7d73]">Receivables</span><b className="mt-2 block text-lg">{money(Math.max(0, salesTotal - paidTotal) || 60500)}</b></div><div className="rounded-xl border p-4"><span className="text-xs text-[#6f7d73]">Daily turnover</span><b className="mt-2 block text-lg">₦284,500</b></div><div className="rounded-xl border p-4"><span className="text-xs text-[#6f7d73]">Monthly turnover</span><b className="mt-2 block text-lg">₦8,540,000</b></div></div></Card></div><Card className="mt-5 p-5"><h2 className="font-semibold">Sales by staff</h2><div className="mt-4 flex justify-between border-b pb-3 text-sm"><span>Samuel Nwosu</span><b>{sales.length || 18} sales · {money(salesTotal || 1284500)}</b></div><div className="mt-4 flex justify-between text-sm"><span>Balance sheet</span><b>Assets ₦4,180,000 · Liabilities ₦60,500</b></div></Card></> }

function Expenses({ onSaved }: any) { const [items, setItems] = useState([{ name: 'Shop rent', amount: 45000 }, { name: 'Transport', amount: 12500 }]); const [name, setName] = useState(''); const [amount, setAmount] = useState(''); const save = () => { if (!name.trim() || !Number(amount) || Number(amount) <= 0) return onSaved('Enter an expense and a valid amount'); setItems(current => [...current, { name: name.trim(), amount: Number(amount) }]); setName(''); setAmount(''); onSaved('Expense saved successfully') }; return <><Heading eyebrow="Expenses" title="Business expenses" description="Record operating costs and keep your profit report accurate." action={<Button onClick={save}><Plus className="size-4" /> Save expense</Button>} /><Card className="p-5"><div className="grid gap-3 sm:grid-cols-[1fr_180px_auto]"><input value={name} onChange={e => setName(e.target.value)} placeholder="Expense description" className="h-10 rounded-lg border px-3 text-sm" /><input type="number" min="1" value={amount} onChange={e => setAmount(e.target.value)} placeholder="Amount" className="h-10 rounded-lg border px-3 text-sm" /><Button onClick={save}>Save expense</Button></div></Card><Card className="mt-5"><div className="border-b p-4 font-semibold">Recent expenses</div>{items.map((item, index) => <div key={`${item.name}-${index}`} className="flex justify-between border-b p-4 text-sm"><span>{item.name}</span><b>{money(item.amount)}</b></div>)}</Card></> }

function StaffLegacy({ onAdd, onAction }: any) { const employees = [['Ada Nwosu', 'Manager', 'Lekki, Ikeja', 'Active', 'Today, 09:42'], ['Samuel Okafor', 'Cashier', 'Lekki branch', 'Active', 'Today, 08:15'], ['Ifeoma Bello', 'Accountant', 'All branches', 'Active', 'Yesterday, 17:30'], ['Chinedu Obi', 'Stock Keeper', 'Ajah branch', 'Suspended', 'Sep 24, 14:10']]; return <><Heading eyebrow="Staff" title="Staff & access" description="Manage employee accounts, branch access and permissions." action={<Button onClick={onAdd}><Plus className="size-4" /> Add employee</Button>} /><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><Stat label="Total employees" value="12" detail="+2 this month" /><Stat label="Active now" value="9" detail="Across 3 branches" /><Stat label="Roles" value="5" detail="1 custom role" /><Stat label="Pending sync" value="3" detail="Sync automatically" orange /></div><Card className="mt-6 overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b p-5"><div><h2 className="font-semibold">Employee accounts</h2><p className="mt-1 text-xs text-[#89958c]">Owner and admin controls for your team.</p></div><Button variant="outline" onClick={() => onAction('roles')}><Users className="size-4" /> Manage roles</Button></div><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-sm"><thead className="bg-[#f8faf7] text-xs text-[#758278]"><tr><th className="px-5 py-3 font-semibold">Employee</th><th className="px-5 py-3 font-semibold">Role</th><th className="px-5 py-3 font-semibold">Branch access</th><th className="px-5 py-3 font-semibold">Status</th><th className="px-5 py-3 font-semibold">Last login</th><th className="px-5 py-3 font-semibold">Actions</th></tr></thead><tbody>{employees.map(([name, role, branches, status, login]) => <tr key={name} className="border-t"><td className="px-5 py-4 font-medium">{name}</td><td className="px-5 py-4">{role}</td><td className="px-5 py-4 text-[#657268]">{branches}</td><td className="px-5 py-4"><span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${status === 'Active' ? 'bg-[#e8f5ea] text-[#39724a]' : 'bg-[#fbe9e7] text-[#b34a3c]'}`}>{status}</span></td><td className="px-5 py-4 text-[#657268]">{login}</td><td className="px-5 py-4"><button onClick={() => onAction(`Manage ${name}`)} className="text-xs font-semibold text-[#39724a]">Manage</button></td></tr>)}</tbody></table></div></Card><Card className="mt-6 p-5"><h2 className="font-semibold">Quick access controls</h2><p className="mt-1 text-sm text-[#89958c]">Review security activity, signed-in devices and role permissions.</p><div className="mt-5 grid gap-3 sm:grid-cols-3">{[['Audit log', 'See who changed what', 'audit', ClipboardList], ['Active devices', 'Sign out sessions', 'devices', Wifi], ['Roles', 'Set staff limits', 'roles', Users]].map(([title, description, type, Icon]: any) => <button key={title} onClick={() => onAction(type)} className="rounded-xl border border-[#edf0ec] p-4 text-left hover:border-[#b7d5bb]"><Icon className="size-5 text-[#39724a]" /><div className="mt-3 text-sm font-semibold">{title}</div><div className="mt-1 text-xs text-[#89958c]">{description}</div></button>)}</div></Card></> }
function Staff({ employees = [], onAdd, onAction, onManage, rolePermissions = {}, onPermissionChange, onCreateRole }: any) {
  const roles = ['Owner', 'Manager', 'Cashier', 'Stock Keeper', 'Accountant']
  const permissions = ['Sales', 'Inventory', 'Customers', 'Accounting', 'Expenses', 'Staff']
  return <><Heading eyebrow="Staff" title="Staff & access" description="Manage employee accounts, branch access and permissions." action={<Button onClick={onAdd}><Plus className="size-4" /> Add employee</Button>} /><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><Stat label="Total employees" value={String(employees.length)} detail="Team accounts" /><Stat label="Active now" value={String(employees.filter((e: any) => e.status === 'Active').length)} detail="Across branches" /><Stat label="Roles" value={String(roles.length)} detail="Permission templates" /><Stat label="Pending sync" value="0" detail="Sync automatically" /></div><Card className="mt-6 overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b p-5"><div><h2 className="font-semibold">Employee accounts</h2><p className="mt-1 text-xs text-[#89958c]">Edit profile, status, role and branch access.</p></div><Button variant="outline" onClick={() => onAction('roles')}><Users className="size-4" /> Manage roles</Button></div><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-sm"><thead className="bg-[#f8faf7] text-xs text-[#758278]"><tr>{['Employee','Role','Branch access','Status','Last login','Actions'].map(h => <th key={h} className="px-5 py-3 font-semibold">{h}</th>)}</tr></thead><tbody>{employees.map((employee: any) => <tr key={employee.id} className="border-t"><td className="px-5 py-4"><b>{employee.name}</b><div className="text-xs text-[#89958c]">{employee.username}</div></td><td className="px-5 py-4">{employee.role}</td><td className="px-5 py-4 text-[#657268]">{employee.branches}</td><td className="px-5 py-4"><span className={`rounded-full px-2 py-1 text-xs font-semibold ${employee.status === 'Active' ? 'bg-[#e6f3e6] text-[#39724a]' : 'bg-[#f7e8e8] text-[#a14949]'}`}>{employee.status}</span></td><td className="px-5 py-4 text-[#657268]">{employee.login}</td><td className="px-5 py-4"><Button size="sm" variant="outline" onClick={() => onManage(employee)}>Manage</Button></td></tr>)}</tbody></table></div></Card><Card className="mt-6 overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b p-5"><div><h2 className="font-semibold">Role access matrix</h2><p className="mt-1 text-xs text-[#89958c]">Changes apply to this business and are saved with each role.</p></div><Button onClick={onCreateRole}><Plus className="size-4" /> Create role</Button></div><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="bg-[#f8faf7] text-xs text-[#758278]"><tr><th className="px-5 py-3">Role</th>{permissions.map(permission => <th key={permission} className="px-3 py-3 text-center">{permission}</th>)}</tr></thead><tbody>{roles.map(role => <tr key={role} className="border-t"><td className="px-5 py-4 font-semibold">{role}</td>{permissions.map(permission => <td key={permission} className="px-3 py-4 text-center"><input type="checkbox" checked={(rolePermissions[role] || []).includes(permission)} onChange={e => onPermissionChange?.(role, permission, e.target.checked)} aria-label={`${role} ${permission}`} /></td>)}</tr>)}</tbody></table></div></Card></>
}

function Branches({ onAction }: any) { return <><Heading eyebrow="Branches" title="Business branches" description="Manage locations, stock and performance." action={<Button onClick={() => onAction('branch')}><Plus className="size-4" /> Add branch</Button>} /><div className="grid gap-4 sm:grid-cols-3">{[['Lekki branch', 'Active · 9 staff', '₦284,500'], ['Ikeja branch', 'Active · 6 staff', '₦192,300'], ['Ajah branch', 'Setup pending', '₦0']].map(([name, status, value]) => <Card key={name} className="p-5"><Building2 className="size-5 text-[#39724a]" /><h2 className="mt-4 font-semibold">{name}</h2><p className="mt-1 text-xs text-[#89958c]">{status}</p><b className="mt-5 block">{value} today</b></Card>)}</div></> }
function Quotations({ onAction }: any) { return <><Heading eyebrow="Quotations" title="Create quotation" description="Prepare and share customer quotations." action={<Button onClick={() => onAction('Quotation created')}><Plus className="size-4" /> New quotation</Button>} /><Card className="p-5"><div className="grid gap-3 sm:grid-cols-2"><input placeholder="Customer name" className="h-10 rounded-lg border px-3 text-sm" /><input placeholder="Customer phone" className="h-10 rounded-lg border px-3 text-sm" /><textarea placeholder="Items and quantities" className="min-h-28 rounded-lg border p-3 text-sm sm:col-span-2" /></div><div className="mt-4 flex gap-2"><Button onClick={() => onAction('Quotation saved')}><Check className="size-4" /> Save quotation</Button><Button variant="outline" onClick={() => onAction('Quotation ready to share')}><Share2 className="size-4" /> Share</Button></div></Card></> }

function RoleCreator({ close, save }: any) { const [name, setName] = useState(''); const [permissions, setPermissions] = useState<string[]>([]); const available = ['Sales', 'Inventory', 'Customers', 'Accounting', 'Expenses', 'Staff']; const toggle = (permission: string) => setPermissions(current => current.includes(permission) ? current.filter(item => item !== permission) : [...current, permission]); return <div className="fixed inset-0 z-30 flex items-center justify-center bg-[#1d2b22]/30 p-4"><div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl"><div className="flex items-start justify-between"><div><h2 className="text-lg font-bold">Create new role</h2><p className="mt-1 text-xs text-[#89958c]">Name the role and choose the areas it can access.</p></div><button onClick={close} aria-label="Close"><X className="size-5" /></button></div><form className="mt-5" onSubmit={event => { event.preventDefault(); save(name, permissions) }}><label className="text-xs font-semibold text-[#647269]">Role name<input required value={name} onChange={event => setName(event.target.value)} placeholder="e.g. Sales Supervisor" className="mt-1 h-10 w-full rounded-lg border px-3 text-sm" /></label><fieldset className="mt-5"><legend className="text-xs font-semibold text-[#647269]">Initial access</legend><div className="mt-2 grid grid-cols-2 gap-2">{available.map(permission => <label key={permission} className="flex items-center gap-2 rounded-lg border p-3 text-sm"><input type="checkbox" checked={permissions.includes(permission)} onChange={() => toggle(permission)} />{permission}</label>)}</div></fieldset><div className="mt-5 flex justify-end gap-2"><Button type="button" variant="outline" onClick={close}>Cancel</Button><Button type="submit"><Plus className="size-4" /> Create role</Button></div></form></div></div> }

function EmployeeEditor({ employee, close, save }: any) { const [data, setData] = useState({ ...employee }); return <div className="fixed inset-0 z-30 flex items-center justify-center bg-[#1d2b22]/30 p-4"><div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl"><div className="flex items-start justify-between"><div><h2 className="text-lg font-bold">Manage employee</h2><p className="mt-1 text-xs text-[#89958c]">Update account details, access and status.</p></div><button onClick={close} aria-label="Close"><X className="size-5" /></button></div><form className="mt-5 flex flex-col gap-3" onSubmit={e => { e.preventDefault(); save(data) }}><label className="text-xs font-semibold text-[#647269]">Full name<input value={data.name} onChange={e => setData({ ...data, name: e.target.value })} className="mt-1 h-10 w-full rounded-lg border px-3 text-sm" /></label><label className="text-xs font-semibold text-[#647269]">Username<input value={data.username} onChange={e => setData({ ...data, username: e.target.value })} className="mt-1 h-10 w-full rounded-lg border px-3 text-sm" /></label><label className="text-xs font-semibold text-[#647269]">Role<select value={data.role} onChange={e => setData({ ...data, role: e.target.value })} className="mt-1 h-10 w-full rounded-lg border bg-white px-3 text-sm"><option>Owner</option><option>Manager</option><option>Cashier</option><option>Stock Keeper</option><option>Accountant</option></select></label><label className="text-xs font-semibold text-[#647269]">Branch access<input value={data.branches} onChange={e => setData({ ...data, branches: e.target.value })} className="mt-1 h-10 w-full rounded-lg border px-3 text-sm" /></label><label className="text-xs font-semibold text-[#647269]">Status<select value={data.status} onChange={e => setData({ ...data, status: e.target.value })} className="mt-1 h-10 w-full rounded-lg border bg-white px-3 text-sm"><option>Active</option><option>Suspended</option></select></label><div className="mt-2 flex justify-end gap-2"><Button type="button" variant="outline" onClick={close}>Cancel</Button><Button type="submit"><Check className="size-4" /> Save changes</Button></div></form></div></div> }

function RecordModal({ type, close, save }: any) { const [data, setData] = useState<any>({ role: 'Cashier', branches: 'Lekki branch' }); const [showPassword, setShowPassword] = useState(false); const [password, setPassword] = useState(''); const fields = type === 'product' ? [['name', 'Product name'], ['quantity', 'Quantity'], ['cost', 'Cost price'], ['price', 'Selling price'], ['category', 'Category']] : type === 'customer' ? [['name', 'Customer name'], ['phone', 'Phone number'], ['location', 'Location'], ['outstanding', 'Outstanding amount']] : [['name', 'Full name'], ['username', 'Phone or email (username)'], ['role', 'Role template'], ['branches', 'Branch access']]; const generatePassword = () => { const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#'; const next = Array.from({ length: 14 }, (_, index) => chars[(index * 17 + Date.now()) % chars.length]).join(''); setPassword(next) }; return <div className="fixed inset-0 z-30 flex items-center justify-center bg-[#1d2b22]/30 p-4"><div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl"><div className="flex justify-between"><div><h2 className="text-lg font-bold">Add {type === 'employee' ? 'employee' : type}</h2><p className="mt-1 text-xs text-[#89958c]">{type === 'employee' ? 'Create a secure account with limited access.' : 'Enter the record details below.'}</p></div><button onClick={close} aria-label="Close"><X className="size-5" /></button></div><form onSubmit={e => { e.preventDefault(); save({ ...data, temporaryPassword: password }) }} className="mt-5 flex flex-col gap-3">{fields.map(([key, label]) => <label key={key} className="text-xs font-semibold text-[#647269]">{label}{key === 'role' ? <select value={data[key] || ''} onChange={e => setData({ ...data, [key]: e.target.value })} className="mt-1 h-10 w-full rounded-lg border bg-white px-3 text-sm"><option>Owner</option><option>Manager</option><option>Cashier</option><option>Stock Keeper</option><option>Accountant</option></select> : key === 'branches' ? <select value={data[key] || ''} onChange={e => setData({ ...data, [key]: e.target.value })} className="mt-1 h-10 w-full rounded-lg border bg-white px-3 text-sm"><option>Lekki branch</option><option>Ikeja branch</option><option>Ajah branch</option><option>All branches</option></select> : <input required type={['quantity', 'cost', 'price', 'outstanding'].includes(key) ? 'number' : 'text'} value={data[key] || ''} onChange={e => setData({ ...data, [key]: e.target.value })} className="mt-1 h-10 w-full rounded-lg border px-3 text-sm" />}</label>)}{type === 'employee' && <div><label className="text-xs font-semibold text-[#647269]">Temporary password<div className="mt-1 flex gap-2"><input required minLength={10} type={showPassword ? 'text' : 'password'} value={password} onChange={e => setPassword(e.target.value)} placeholder="Set or generate a strong password" className="h-10 min-w-0 flex-1 rounded-lg border px-3 text-sm" /><Button type="button" variant="outline" onClick={() => setShowPassword(value => !value)}>{showPassword ? 'Hide' : 'Show'}</Button></div></label><Button type="button" variant="outline" className="mt-2 w-full" onClick={generatePassword}>Generate strong password</Button><p className="mt-2 text-xs text-[#89958c]">The employee will be required to change this password on first login.</p></div>}<Button type="submit">Create {type === 'employee' ? 'employee account' : type}</Button></form></div></div> }

function ActionOverlay({ type, close }: { type: Exclude<Overlay, null>; close: () => void }) { const content = type === 'audit' ? { title: 'Audit log', description: 'Recent activity across your business.', rows: ['Samuel completed a sale · 2 minutes ago', 'Ada added a new customer · 1 hour ago', 'Samuel updated Peak Milk stock · Yesterday'] } : type === 'devices' ? { title: 'Active devices', description: 'Review and manage signed-in devices.', rows: ['This device · Chrome · Active now', 'Front desk tablet · Active 18 minutes ago', 'Manager phone · Active yesterday'] } : type === 'roles' ? { title: 'Roles and permissions', description: 'Control what each team role can access.', rows: ['Owner · Full access', 'Manager · Sales, inventory and reports', 'Cashier · Point of sale only'] } : { title: 'Add branch', description: 'Create a new business location.', rows: [] }; return <div className="fixed inset-0 z-30 flex items-center justify-center bg-[#1d2b22]/30 p-4"><div className="w-full max-w-lg rounded-2xl bg-white p-6 shadow-xl"><div className="flex items-start justify-between"><div><h2 className="text-xl font-bold">{content.title}</h2><p className="mt-1 text-sm text-[#7d8980]">{content.description}</p></div><button onClick={close} aria-label="Close"><X className="size-5" /></button></div>{type === 'branch' ? <div className="mt-5 grid gap-3 sm:grid-cols-2"><input placeholder="Branch name" className="h-10 rounded-lg border px-3 text-sm" /><input placeholder="Location" className="h-10 rounded-lg border px-3 text-sm" /><Button onClick={close}>Save branch</Button></div> : <div className="mt-5 flex flex-col gap-3">{content.rows.map(row => <div key={row} className="rounded-xl bg-[#f6f8f5] p-3 text-sm">{row}</div>)}<Button variant="outline" onClick={close}>Close</Button></div>}</div></div> }

function NotificationPanel({ items, close }: any) { return <div className="fixed inset-0 z-40 flex justify-end bg-[#1d2b22]/20 p-4"><div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"><div className="flex items-center justify-between"><div><h2 className="text-xl font-bold">Notifications</h2><p className="mt-1 text-sm text-[#7d8980]">Recent activity from your workspace.</p></div><button onClick={close} aria-label="Close"><X className="size-5" /></button></div><div className="mt-6 flex flex-col gap-3">{items.map((item: any) => <div key={item.title} className="rounded-xl border border-[#e2ebe1] p-4"><div className="flex items-start gap-3"><span className="mt-1 size-2 rounded-full bg-[#d97845]" /><div><b className="text-sm">{item.title}</b><p className="mt-1 text-sm text-[#657268]">{item.detail}</p><p className="mt-2 text-xs text-[#9aa49c]">{item.time}</p></div></div></div>)}</div></div></div> }

function SettingsPanel({ businessName, adminName, logo, setBusinessName, setAdminName, setLogo, close, save }: any) { return <div className="fixed inset-0 z-40 flex items-center justify-center bg-[#1d2b22]/30 p-4"><div className="w-full max-w-lg rounded-2xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between"><div><h2 className="text-xl font-bold">Workspace settings</h2><p className="mt-1 text-sm text-[#7d8980]">Customize the dashboard for your business.</p></div><button onClick={close} aria-label="Close"><X className="size-5" /></button></div><div className="mt-6 flex flex-col gap-4"><label className="text-sm font-semibold">Business name<input value={businessName} onChange={e => setBusinessName(e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#d8e5d8] px-3" /></label><label className="text-sm font-semibold">Admin name<input value={adminName} onChange={e => setAdminName(e.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#d8e5d8] px-3" /></label><label className="flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-[#b9d9bc] p-4 text-sm font-semibold text-[#39724a]"><Upload className="size-5" /> Upload business logo<input type="file" accept="image/*" className="sr-only" onChange={event => { const file = event.target.files?.[0]; if (file) setLogo(URL.createObjectURL(file)) }} /></label>{logo && <img src={logo} alt="Business logo preview" className="size-16 rounded-xl object-cover" />}</div><div className="mt-6 flex justify-end gap-2"><Button variant="outline" onClick={close}>Cancel</Button><Button onClick={save}>Save settings</Button></div></div></div> }
